{
  "PROP-6a4369e9-post-003": {
    "property_id": "PROP-6a4369e9-post-003",
    "audit_result": {
      "property_id": "PROP-6a4369e9-post-003",
      "classification": "vulnerability",
      "code_path": "beacon_node/beacon_chain/src/data_column_verification.rs::new_for_block_publishing::L221-250",
      "proof_trace": "Columns from EL (engine_getBlobs) bypass gossip verification via new_for_block_publishing, which skips signature, parent, inclusion proof, and KZG verification, yet are treated as gossip-verified when passed to process_gossip_data_columns. Malicious local EL can inject invalid columns that bypass all consensus validation.",
      "attack_scenario": "Compromised local EL returns crafted columns via engine_getBlobs with invalid signatures/proofs. These bypass gossip checks via new_for_block_publishing (L221-250), get published to network via publish_column_sidecars, and propagated as valid. Network peers reject them after full verification, causing failed block import and potential slashing.",
      "checklist_id": "PROP-6a4369e9-post-003"
    },
    "text": "After distributed blob publishing, imported columns must behave as if received via gossip.",
    "assertion": "forall col from EL: imported(col) => treated_as_gossip(col) == true",
    "covers": "SG-010",
    "severity": "HIGH",
    "type": "post-condition"
  }
}

